import json
import os
import sys
import urllib.request


def main():
    prompt = " ".join(sys.argv[1:]) if len(sys.argv) > 1 else sys.stdin.read()
    if not prompt.strip():
        raise SystemExit("Adj meg egy promptot argumentumként vagy stdin-en.")

    key = os.environ.get("OPENROUTER_API_KEY", "").strip()
    if not key:
        raise SystemExit("Állítsd be az OPENROUTER_API_KEY környezeti változót.")

    body = json.dumps(
        {
            "model": "stealth/space-bunny-alpha",
            "messages": [{"role": "user", "content": prompt}],
            "max_completion_tokens": 131072,
            "reasoning_effort": "max",
        },
        ensure_ascii=False,
    ).encode("utf-8")
    request = urllib.request.Request(
        "https://openrouter.ai/api/v1/chat/completions",
        data=body,
        headers={
            "Authorization": f"Bearer {key}",
            "Content-Type": "application/json; charset=utf-8",
            "Accept": "application/json",
        },
        method="POST",
    )

    try:
        with urllib.request.urlopen(request, timeout=3600) as response:
            result = json.load(response)
    except urllib.error.HTTPError as error:
        details = error.read().decode("utf-8", errors="replace")
        try:
            parsed = json.loads(details)
            api_error = parsed.get("error") if isinstance(parsed, dict) else None
            if isinstance(api_error, dict):
                details = str(api_error.get("message") or details)
        except json.JSONDecodeError:
            pass
        raise SystemExit(f"OpenRouter HTTP {error.code}: {details or error.reason}") from None
    except (urllib.error.URLError, TimeoutError) as error:
        raise SystemExit(f"Hálózati hiba: {error}") from None
    except (json.JSONDecodeError, UnicodeDecodeError) as error:
        raise SystemExit(f"Érvénytelen API-válasz: {error}") from None

    if not isinstance(result, dict):
        raise SystemExit("Érvénytelen API-válasz: a válasz nem JSON-objektum.")
    api_error = result.get("error")
    if api_error:
        message = api_error.get("message", api_error) if isinstance(api_error, dict) else api_error
        raise SystemExit(f"OpenRouter-hiba: {message}")
    choices = result.get("choices")
    if not isinstance(choices, list) or not choices or not isinstance(choices[0], dict):
        raise SystemExit("Érvénytelen API-válasz: hiányzik a választási lista.")
    message = choices[0].get("message")
    content = message.get("content") if isinstance(message, dict) else None
    if not isinstance(content, str) or not content:
        reason = choices[0].get("finish_reason")
        raise SystemExit(f"Az API nem adott szöveges választ. Befejezés oka: {reason or 'ismeretlen'}.")
    print(content)


if __name__ == "__main__":
    main()
